1	package config
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"strconv"
8		"time"
9	)
10	
11	const defaultMaxUploadSize = 10 * 1024 * 1024 // 10MB
12	
13	type Config struct {
14		Port              string
15		S3BucketName      string
16		AWSRegion         string
17		S3PresignEndpoint string
18		PresignExpiry     time.Duration
19		MaxUploadSize     int64
20		S3PathStyle       bool
21	}
22	
23	func Load() (*Config, error) {
24		cfg := &Config{
25			Port:         os.Getenv("PORT"),
26			S3BucketName: os.Getenv("S3_BUCKET_NAME"),
27			AWSRegion:    os.Getenv("AWS_REGION"),
28		}
29	
30		cfg.S3PathStyle = os.Getenv("S3_PATH_STYLE") == "true"
31		cfg.S3PresignEndpoint = os.Getenv("S3_PRESIGN_ENDPOINT")
32	
33		if v := os.Getenv("MAX_UPLOAD_SIZE"); v != "" {
34			n, err := strconv.ParseInt(v, 10, 64)
35			if err != nil {
36				return nil, fmt.Errorf("MAX_UPLOAD_SIZE is invalid: %w", err)
37			}
38			if n <= 0 {
39				return nil, errors.New("MAX_UPLOAD_SIZE must be positive")
40			}
41			cfg.MaxUploadSize = n
42		} else {
43			cfg.MaxUploadSize = defaultMaxUploadSize
44		}
45	
46		if cfg.Port == "" {
47			cfg.Port = "8080"
48		}
49	
50		if v := os.Getenv("PRESIGN_EXPIRY"); v != "" {
51			d, err := time.ParseDuration(v)
52			if err != nil {
53				return nil, fmt.Errorf("PRESIGN_EXPIRY is invalid: %w", err)
54			}
55			cfg.PresignExpiry = d
56		} else {
57			cfg.PresignExpiry = 15 * time.Minute
58		}
59	
60		if cfg.S3BucketName == "" {
61			return nil, errors.New("S3_BUCKET_NAME is required")
62		}
63	
64		if cfg.AWSRegion == "" {
65			return nil, errors.New("AWS_REGION is required")
66		}
67	
68		return cfg, nil
69	}
